begin;

-- Local food listings for Cuyahoga County and the farms of Cuyahoga Valley National Park, from the Ohio Department of
-- Job and Family Services 2026 Farmers' Market Directory, Signal Cleveland's local produce guide, the City of Cleveland /
-- OSU Extension Summer Sprout Cleveland Food System Map, and the National Park Service. Garden and farm managers'
-- personal phone numbers and emails are deliberately left out; a manager who claims a listing adds their own.
-- Running it again refreshes unclaimed listings; a listing a grower has claimed is theirs and is left alone.
on conflict (slug) do update set kind = excluded.kind,name = excluded.name,detail = excluded.detail,address = excluded.address,city = excluded.city,
  area_id = excluded.area_id,region = excluded.region,schedule = excluded.schedule,season = excluded.season,snap = excluded.snap,perks = excluded.perks,
  url = excluded.url,phone = excluded.phone,lat = excluded.lat,lng = excluded.lng,source = excluded.source,updated_at = now()
  where neighborhood.food_listings.owner_id is null;
commit;
